          "title": "光伏价格战没有结束，但项目判断已经从单看低价转向看交付与兑现",
          "summary": "国家能源局6月12日转载的报道再次强调，光伏制造端正在经历从拼低价到拼技术、拼交付、拼信用的变化。海外反补贴、出口退税调整和国内亏损压力叠加，产业链更像是在做一次系统性筛选。",
          "why_it_matters": "对项目端来说，组件价格再低也不等于收益更好。真正决定现金流的，是供货稳定、质保兑现、海外认证和售后成本。现在做测算，不能只看招标单价，还要把低价风险、交期风险和合规摩擦一起纳入。",
